package jp.tapmarker;
import java.io.*;import java.util.*;import java.util.zip.*;

/** Timestamp-disjoint real video covers acquisition, feeding, mission claims and ad recovery. */
public final class Video6725ReplayTest {
 static int checks;static Map<String,float[]> refs;static final Map<String,VirtualPresetProfileTest.Image> images=new LinkedHashMap<>();
 static void check(boolean value,String why){checks++;if(!value)throw new AssertionError(why);}
 static void load()throws Exception{refs=VirtualPresetProfileTest.canonical("tests/image6727-references.bin");try(DataInputStream in=new DataInputStream(new GZIPInputStream(new FileInputStream("tests/video6725-replay.bin.gz")))){int n=in.readInt();for(int i=0;i<n;i++)images.put(in.readUTF(),new VirtualPresetProfileTest.Image(in));check(n==137&&in.read()==-1,"all 137 replay images complete");}for(String t:new String[]{"25.2","72.6","0.6","13.8","11.9","84.05","75.6","6.2","62.0","81.0"})check(!images.containsKey(t)&&!images.containsKey(t+"-native"),"training timestamp is not a replay frame: "+t);}
 static final class Run {
  final PhaseEngine e=new PhaseEngine();final PoipoiLayout layout;final AdHomeRecovery home=new AdHomeRecovery();Map<String,float[]> samples;long clock=1000;
  Run(String state){PoipoiPreset.install(e,refs);e.strictRuntime=true;layout=PoipoiLayout.install(e,refs);AdCloseAutomaton.install(e,PoipoiPreset.APP);e.enter(PoipoiPreset.P+state,0);}
  Map<String,float[]> sample(String id,long at){VirtualPresetProfileTest.Image im=images.get(id);return samples=layout.sampleRelative(e.activeRegions(),im.width,im.height,im,at);}
  PhaseEngine.Watch event(String id){e.observe(sample(id,clock),clock);check(e.poll()==null,"first image awaits confirmation: "+id+" / "+e.current);clock+=350;e.observe(sample(id,clock),clock);return e.poll();}
  void finish(PhaseEngine.Watch w){check(w!=null,"an observed transition is available");e.finish(w,clock+20);clock+=500;}
 }
 static void classification(){
  String[][] groups={{"offline","0.8","1.2"},{"bonus","13.2","13.6","14.2","95.5"},{"reward","10.8","83.7","84.2","84.2-native"},{"missions","4.2","12.2","75.5","85.2","87.5"},{"mission-tap","2.2","2.8","72.2","72.9","73.7","2.2-native","72.9-native","74.0","74.2"},{"main","16.0","26.0","38.0","50.0","60.0","68.0","70.0","72.0","96.5","98.5"}};
  for(String state:new String[]{"check","verify","ad","offline-wait"})for(String[] group:groups)for(int i=1;i<group.length;i++){Run r=new Run(state);PhaseEngine.Watch w=r.event(group[i]);check(w!=null&&w.nextPhase.equals(PoipoiPreset.P+group[0]),"classifies "+group[i]+" as "+group[0]+" / "+state+" / "+r.e.diagnostic);r.finish(w);check(PoipoiPreset.playable(r.e,r.samples)==group[0].equals("main"),"only normal feeding enables main input: "+group[i]);}
  for(String state:new String[]{"mission-ad","mission-verify","mission-opening","claim-wait"}){Run r=new Run(state);PhaseEngine.Watch w=r.event("16.0");check(w!=null&&w.nextPhase.equals(PoipoiPreset.P+"mission-tap"),"collection intent survives ordinary game resumption: "+state);}
 }
 static void mainLoop(){
  Run r=new Run("main");for(String id:new String[]{"0.0","16.0","18.0","26.0","28.0","30.0","32.0","34.0","36.0","38.0","46.0","48.0","50.0","52.0","54.0","56.0","58.0","60.0","68.0","70.0","72.0","71.5","96.5","98.5"}){r.sample(id,1000);check(PoipoiPreset.playable(r.e,r.samples),"a partial satisfaction value does not interrupt normal tapping: "+id);PhaseEngine.Watch full=r.e.rule(PoipoiPreset.P+"main-full");check(full.distance(r.samples.get(full.regionId))>full.threshold,"partial values are not 100.00%: "+id);r.e.observe(r.samples,1000);check(r.e.poll()==null,"ordinary feeding creates no extra button input: "+id);}
  for(String id:new String[]{"0.8","13.6","4.2","12.2","84.2","2.2","72.9","74.2","6.8","81.5","8.4","22.4","92.5"}){r.sample(id,2000);check(!PoipoiPreset.playable(r.e,r.samples),"bonus, full/badge, missions, reward, CM and HOME stop normal tapping: "+id);}
  r.sample("26.0",2500);check(!ContinuousTapPolicy.allow(r.e,true,false,false,false,false,2500,2500),"external package blocks input");check(!ContinuousTapPolicy.allow(r.e,true,false,false,true,true,2500,2500),"HOME handoff blocks input");check(!ContinuousTapPolicy.allow(r.e,true,false,false,false,true,2500,4000),"stale game frame blocks input");
 }
 static void controls(){
  for(String[] row:new String[][]{{"offline","0.8","offline-tap"},{"bonus","13.6","bonus-tap"},{"reward","84.2","reward-tap"},{"mission-tap","16.0","mission-button-tap"},{"missions","4.2","get-tap"},{"missions","75.5","get-tap"},{"missions","12.2","mission-back"},{"missions","87.5","mission-back"}}){
   Run r=new Run(row[0]);PhaseEngine.Watch w=r.event(row[1]);check(w!=null&&w.id.equals(PoipoiPreset.P+row[2])&&w.action==PhaseEngine.CENTER,"only verified control selected: "+Arrays.toString(row));VirtualPresetProfileTest.Image im=images.get(row[1]);float[] p=r.layout.pointRelative(w,r.samples,im.width,im.height);check(p!=null,"control has current-image touch bounds");check(r.e.confirmsAction(w,r.e.current,r.e.epoch,r.samples),"current control passes preflight");check(!r.e.confirmsAction(w,r.e.current,r.e.epoch+1,r.samples),"old state entry cannot authorize control");check(!r.e.confirmsAction(w,r.e.current,r.e.epoch,r.sample("6.8",2000)),"CM replacing a control cancels preflight");
   if(row[0].equals("offline"))check(p[1]>.64f*im.height&&p[1]<.70f*im.height,"ordinary offline acquisition is below the multiplier CM button");if(row[0].equals("bonus"))check(p[1]>.61f*im.height&&p[1]<.66f*im.height,"continue is below the optional CM button");if(row[2].equals("mission-button-tap"))check(p[0]<.32f*im.width&&p[1]>.75f*im.height,"opens the lower-left mission, not a boost or help button");if(row[2].equals("get-tap"))check(p[0]>.70f*im.width&&p[1]>.70f*im.height,"claims the actual visible completed row");if(row[2].equals("mission-back"))check(p[0]<.08f*im.width&&p[1]<.21f*im.height,"empty mission list uses Back and never yellow Play");
  }
  for(String id:new String[]{"12.2","76.0","85.2","86.2","88.5","94.5"}){Run r=new Run("missions");r.sample(id,1000);PhaseEngine.Watch get=r.e.rule(PoipoiPreset.P+"get-tap");check(get.distance(r.samples.get(get.regionId))>get.threshold,"yellow Play is never treated as Get: "+id);}
 }
 static void homeRecovery(){
  Set<String> positives=new HashSet<>(Arrays.asList("6.0","20.0","40.0","78.0","80.0","82.0","90.0","5.8","6.8","18.8","19.4","20.4","40.5","41.5","61.3","62.5","76.5","77.5","79.5","80.5","81.5","82.2","82.7","83.2","89.5","62.5-native","81.5-native"));
  for(String id:images.keySet()){Run r=new Run("ad");VirtualPresetProfileTest.Image im=images.get(id);r.sample(id,1000);check(AdHomeRecovery.visible(r.samples,im.width,im.height)==positives.contains(id),"independent ad-counter/attribution evidence: "+id);check(!r.home.observe(r.e,r.samples,im.width,im.height,1000,1000),"first ad frame does not send HOME");check(!r.home.observe(r.e,r.samples,im.width,im.height,1000,1100),"duplicate screenshot notification is not a new ad frame");r.sample(id,1350);check(r.home.observe(r.e,r.samples,im.width,im.height,1350,1350)==positives.contains(id),"two fresh frames authorize only this recorded CM: "+id);}
  for(String state:new String[]{"check","verify","mission-ad","mission-verify","claim-wait"}){Run r=new Run(state);VirtualPresetProfileTest.Image im=images.get("81.5");check(!r.home.observe(r.e,r.sample("81.5",1000),im.width,im.height,1000,1000),"new state needs two ad observations");check(r.home.observe(r.e,r.sample("81.5",1350),im.width,im.height,1350,1350),"recorded second ad also supports HOME from "+state);}
  for(int family=0;family<3;family++)for(int part=0;part<2;part++){final VirtualPresetProfileTest.Image im=images.get(family==0?"6.8":family==1?"62.5-native":"81.5-native");final int[] b=RegionMath.bounds(PoipoiAdHomeEvidence.PAIRS[family][part],im.width,im.height);RegionSampler.Pixels absent=(x,y)->x>=b[0]-5&&x<b[2]+5&&y>=b[1]-5&&y<b[3]+5?0xff777777:im.get(x,y);Run r=new Run("ad");Map<String,float[]> s=r.layout.sampleRelative(r.e.activeRegions(),im.width,im.height,absent,1000);check(!s.containsKey(AdHomeRecovery.EVIDENCE),"either missing ad anchor blocks HOME: "+family+" / "+part);}
  Run r=new Run("ad");VirtualPresetProfileTest.Image im=images.get("81.5");r.sample("81.5",1000);check(!r.home.observe(r.e,r.samples,im.width,im.height,1000,1800),"old ad evidence expires");check(!r.home.observe(r.e,r.samples,im.width+1,im.height,1000,1000),"display-size change invalidates ad evidence");r.e.windowRelative=true;check(!AdHomeRecovery.eligible(r.e),"learned-window graph cannot request global HOME");
  for(String id:new String[]{"6.8","7.4","20.4","41.5","62.5","81.5"}){r=new Run("ad");im=images.get(id);r.sample(id,1000);for(String corner:new String[]{AdCloseAutomaton.LEFT,AdCloseAutomaton.RIGHT})for(float[] p:AdCloseAutomaton.candidates(corner,r.samples,im.width,im.height))check(!(p[0]>.55f*im.width&&p[1]<.12f*im.height),"Open Google Play CTA arrow is not an exit target: "+id);}
 }
 static void step(Run r,String image,String expected){PhaseEngine.Watch w=r.event(image);check(w!=null&&w.id.equals(PoipoiPreset.P+expected),"loop step "+image+" -> "+expected+" / "+r.e.current+" / "+r.e.diagnostic);r.finish(w);}
 static void journeys(){
  Run r=new Run("check");step(r,"0.8","check-offline");step(r,"0.8","offline-tap");step(r,"2.2","offline-wait-full");step(r,"3.2","mission-button-tap");step(r,"4.2","mission-opening-missions");step(r,"4.2","get-tap");check(PoipoiPreset.recoveryTarget(r.e.current).equals(PoipoiPreset.P+"mission-verify"),"Get's collection intent survives first CM");r.e.enter(PoipoiPreset.recoveryTarget(r.e.current),r.clock);step(r,"10.8","mission-verify-reward");step(r,"10.8","reward-tap");step(r,"12.2","mission-opening-missions");step(r,"12.2","mission-back");step(r,"13.6","verify-bonus");step(r,"13.6","bonus-tap");step(r,"16.0","mission-verify-game");step(r,"16.0","mission-button-tap");step(r,"12.2","mission-opening-missions");step(r,"12.2","mission-back");step(r,"16.0","verify-game");check(r.e.current.equals(PoipoiPreset.P+"main")&&PoipoiPreset.playable(r.e,r.samples),"first complete cycle resumes feeding");
  step(r,"72.9","main-full");step(r,"74.2","mission-button-tap");step(r,"75.5","mission-opening-missions");step(r,"75.5","get-tap");for(int ad=0;ad<2;ad++){String next=PoipoiPreset.recoveryTarget(r.e.current);check(next.equals(PoipoiPreset.P+"mission-verify"),"collection target survives CM "+(ad+1));r.e.enter(next,r.clock+ad*1000);}step(r,"84.2","mission-verify-reward");step(r,"84.2","reward-tap");step(r,"85.2","mission-opening-missions");step(r,"85.2","mission-back");step(r,"98.5","verify-game");check(PoipoiPreset.playable(r.e,r.samples),"second full/claim/two-CM cycle returns to normal feeding");
 }
 static void geometry(){final VirtualPresetProfileTest.Image im=images.get("26.0");for(int[] size:new int[][]{{360,808},{540,1200},{720,1600}}){final int w=size[0],h=size[1];RegionSampler.Pixels pixels=(x,y)->im.get(Math.min(im.width-1,x*im.width/w),Math.min(im.height-1,y*im.height/h));Run r=new Run("main");Map<String,float[]> s=r.layout.sampleRelative(r.e.activeRegions(),w,h,pixels,1000);check(PoipoiPreset.playable(r.e,s),"resized ordinary game stays playable: "+w+"x"+h);float[] p=r.layout.mainPointRelative(s,w,h);check(p!=null&&p[0]>.4f*w&&p[0]<.6f*w&&p[1]>.54f*h&&p[1]<.67f*h,"feeding target stays on carrots");}
  final VirtualPresetProfileTest.Image full=images.get("72.9-native");for(float[] anchor:PoipoiPreset.GAME){final int[] b=RegionMath.bounds(anchor,full.width,full.height);RegionSampler.Pixels absent=(x,y)->x>=b[0]-5&&x<b[2]+5&&y>=b[1]-5&&y<b[3]+5?0xff777777:full.get(x,y);Run r=new Run("check");Map<String,float[]> s=r.layout.sampleRelative(r.e.activeRegions(),full.width,full.height,absent,1000);PhaseEngine.Watch w=r.e.rule(PoipoiPreset.P+"check-full");check(w.distance(s.get(w.regionId))>w.threshold,"full detection also requires both ordinary game anchors");}
 }
 public static void main(String[] args)throws Exception{load();classification();mainLoop();controls();homeRecovery();journeys();geometry();System.out.println("Video6725ReplayTest: "+checks+" checks passed; Poipoi feeding, exact full/badge, Get-only collection, offline/continue/reward controls, paired ad HOME, two-CM journey and negative/geometry checks; physical device untested");}
}
